import { ViewTransition } from 'react'

// Transition types set via <Link transitionTypes={[...]}>. Navigations
// without a type (browser back/forward, refresh) get no directional slide.
const directional = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

// Wrap each page's root content (not the layout, which persists across
// navigations so enter/exit would never fire there).
export function DirectionalTransition({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <ViewTransition enter={directional} exit={directional} default="none">
      {children}
    </ViewTransition>
  )
}

